// Toolbar.tsx — KiCad's four toolbars (top main, top aux, left options, right draw tools) built
// from the generated spec: plain buttons, split-button groups with a palette (click the arrow or
// press-and-hold, like wx), separators and the aux bar's controls.  The vertical bars are a single
// scrolling column.  The right bar also carries the collab tools app.js keeps in its File menu on
// the desktop, and a hidden `#ltools` marker that tells sch-tools which tool is active.
import { usePluginBarEntries } from "../plugins/PluginUi";
import { Fragment, useCallback, useEffect, useLayoutEffect, useRef, useState, type CSSProperties, type ReactElement, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { actionMeta, isControl, isGroup, isSep, SPEC, type ActionItem, type ControlItem, type GroupItem, type ToolbarItem, type ToolbarLoc } from "../spec";
import { EXTRA_TOOLS, READ_ONLY_OK, ZOOM_LIST, toolFor } from "../tables";
import { gridChoiceText } from "../units";
import { Select, type SelectOption } from "./Select";
import { appState, dispatch, useApp, type Editor } from "../store";
import { isOn, keyFor, runUiAction, titleFor, unavailable, useAvail, type Avail } from "../actions";
import { cx } from "../util";
import { keyName, menuKey } from "../keys";
import { menuScroller, menuSize, menuViewport } from "../menufit";
import { Glyph, KIcon } from "./Icon";
import { LayerSelect, TrackWidthSelect, ViaSizeSelect, ViaStackSelect } from "./PcbControls";

function useEditor(): Editor | null { return useApp((s) => s.document.editor); }

// ---------------------------------------------------------------- the look (Tailwind utilities)
/* `kb`, `on`, `desk`, `kmain`, `glyph`, `ktb`, `ktb-v`, `karrow`, … stay as hook classes (this file and
   sch-tools query them); the styling is entirely the utilities that follow them. */
/* WX_AUI_TOOLBAR_ART::DrawButton: square, a 1px accent rectangle over an accent-tinted fill when hovered or
   checked (lighter when both), darker while pressed; nothing moves.  A disabled button draws no rectangle and
   shows its KiDisabledBitmap (the icon greyed). */
const KB = "kb relative w-7.5 h-7.5 p-0.5 border border-transparent rounded-none bg-transparent text-ink inline-flex items-center justify-center flex-none"
  + " hover:bg-tb-hover hover:border-accent on:bg-tb-hover on:border-accent on:hover:bg-tb-on-hover active:bg-tb-press active:border-accent"
  + " desk:hover:bg-transparent desk:hover:border-transparent desk:active:bg-transparent desk:active:border-transparent desk:[&>*]:grayscale desk:[&>*]:opacity-45"
  + " desk:on:bg-transparent desk:on:border-transparent";
/* No KiCad toolbar ever wraps: wxAuiToolBar keeps its one row (or column) and hides the tools that do
   not fit behind an overflow chevron that pops them up as a menu — ACTION_TOOLBAR's
   `SetOverflowVisible( !GetToolBarFits() )` (common/tool/action_toolbar.cpp:259-266).  OverflowBar
   below does the same on both axes, so nothing is ever cut off at the window edge and the canvas
   never loses height to a second row of buttons.
   In each bar the outer box is the grid cell and holds the chevron; the inner track is what clips,
   so the chevron always stays inside the window even when the tools do not. */
const KTB = "ktb flex items-stretch bg-bench border-b border-line min-w-0";
const KTB_INNER = "ktb-row flex flex-row flex-nowrap items-center justify-start gap-px px-1 py-0.5 flex-1 min-w-0 overflow-hidden [&>*]:flex-none";
const KTB_V = "ktb ktb-v flex flex-col items-center min-h-0 w-8.5 bg-bench";
const KTB_V_INNER = "ktb-col flex flex-col flex-nowrap items-center justify-start gap-px px-0.5 py-1 w-full flex-1 min-h-0 overflow-hidden [&>*]:flex-none";
/* the overflow chevron: KB's look without KB's `relative`, so it stays a plain flex item at the end of the bar */
const KMORE = "kb kmore flex-none w-7.5 h-7.5 p-0.5 border border-transparent rounded-sm bg-transparent text-ink-2 inline-flex items-center justify-center"
  + " hover:bg-paper hover:border-line hover:text-ink [&[hidden]]:hidden";
const KSEL = "ksel h-6 text-sm max-w-[260px]";

// ---------------------------------------------------------------- view-only access
/* A viewer (or a signed-out visitor of a public project) may look, select, measure and inspect, but every tool and
   command that changes the document is greyed out the way KiCad greys an action whose condition fails — the menus
   do the same (MenuBar disabledWhy).  The left bars are display options; the rest is listed here. */
const VIEW_SAFE = new Set<string>([...READ_ONLY_OK, "selectSetRect", "selectSetLasso", "highlightNetTool", "localRatsnestTool", "measureTool", "zoomRedraw", "zoomInCenter", "zoomOutCenter",
  "zoomFitScreen", "zoomFitObjects", "zoomTool", "navigateBack", "navigateUp", "navigateForward", "find", "print", "plot", "runERC", "runDRC", "show3DViewer", "showSymbolBrowser",
  "showFootprintBrowser", "showSymbolEditor", "showFootprintEditor", "showPcbNew", "showEeschema", "generateBOM", "showSimulator",
  ...Object.values(SPEC.toolbars).flatMap((t) => (t.left || []).flatMap((it) => (isGroup(it) ? it.items.map((x) => x.id) : isSep(it) || isControl(it) ? [] : [it.id])))]);
/** Why a toolbar entry is greyed for a viewer; null when it can run. */
/** Why a tool is off for someone who may not edit; a commenter is told they can still comment. */
function viewOnlyWhy(viewOnly: boolean, id: string): string | null {
  if (!viewOnly || !id || VIEW_SAFE.has(id)) return null;
  return appState().canComment ? "Comment-only access" : "View-only access";
}

// ---------------------------------------------------------------- buttons
function ActionButton({ item, a, main }: { item: ActionItem; a: Avail; main?: boolean }) {
  const tool = useApp((s) => s.tool.current);
  const toggles = useApp((s) => s.toggles);
  const panes = useApp((s) => s.panes);
  const id = item.id;
  const meta = actionMeta(id) || item;
  const tid = toolFor(a.editor, id);
  const ro = viewOnlyWhy(useApp((s) => s.viewOnly), id);
  const why = unavailable(a, id) || ro;
  const on = tid ? tool === tid : isOn(id, toggles, panes);
  const menuHandled = a.handled.has(id + ":menu") && !ro;
  return (
    <button type="button" className={cx(KB, main && "kmain", why && "desk", on && "on")} data-uiact={id} data-ktool={tid || undefined} aria-disabled={ro ? true : undefined}
      title={titleFor(a, id) + (ro ? "\n— " + ro : "")} onClick={(ev) => { if (!ro) runUiAction(a, id, ev.currentTarget); }}
      onContextMenu={menuHandled ? (ev) => { ev.preventDefault(); dispatch({ type: "action", id: id + ":menu", anchor: rectOf(ev.currentTarget) }); } : undefined}>
      <KIcon name={meta.icon || "options_generic"} />
    </button>
  );
}
function rectOf(el: Element) { const r = el.getBoundingClientRect(); return { left: r.left, top: r.top, right: r.right, bottom: r.bottom }; }

/* ACTION_TOOLBAR_PALETTE: a strip of the group's buttons, each the size of the toolbar button that opened it, with a
   4px border around them and 1px between; a column under a top toolbar, a row beside a left or right one.  Each
   button has its action's tooltip; pressing one makes it the group's button and runs it.  Escape dismisses it. */
const PALETTE_BORDER = 4;
const PALETTE_OPEN_DELAY = 500;   // ACTION_TOOLBAR's long press, in ms
/** Where the palette goes for a button rect: ACTION_TOOLBAR::popupPalette's per-dock offsets. */
export function palettePlace(r: { left: number; top: number; right: number; bottom: number }, dock: "top" | "left" | "right", w: number, pad = 2): { left: number; top: number; vertical: boolean } {
  if (dock === "left") return { left: r.right + pad + PALETTE_BORDER, top: r.top, vertical: false };
  if (dock === "right") return { left: r.left - (w + pad + PALETTE_BORDER), top: r.top, vertical: false };
  return { left: r.left - PALETTE_BORDER, top: r.bottom + pad, vertical: true };
}

function Palette({ group, wrap, a, onClose, armed }: { group: GroupItem; wrap: HTMLElement; a: Avail; onClose: () => void; armed: { current: boolean } }) {
  const ref = useRef<HTMLDivElement>(null);
  const viewOnly = useApp((s) => s.viewOnly);
  const dock: "top" | "left" | "right" = wrap.closest("#tbRight") ? "right" : wrap.closest(".ktb-v") ? "left" : "top";
  const [style, setStyle] = useState<CSSProperties>({ visibility: "hidden" });
  useLayoutEffect(() => {
    // menufit: kept inside the window; a column longer than the window is cut to it and scrolls with the menus' arrow strips
    const r = wrap.getBoundingClientRect();
    const { w, h } = ref.current ? menuSize(ref.current) : { w: 40, h: 40 }, vp = menuViewport();
    const p = palettePlace(r, dock, w);
    const top = Math.max(4, Math.min(p.top, vp.h - h - 4));
    setStyle({ left: Math.max(4, Math.min(p.left, vp.w - w - 4)) + "px", top: top + "px", maxHeight: vp.h - 4 - top + "px", overflowY: dock === "top" ? "auto" : undefined });
    if (ref.current && dock === "top") menuScroller(ref.current);
  }, [wrap, dock]);
  useEffect(() => {
    const down = (ev: PointerEvent) => { if (ref.current && !ref.current.contains(ev.target as Node)) onClose(); };
    const key = (ev: KeyboardEvent) => { if (ev.key === "Escape") { ev.stopPropagation(); ev.preventDefault(); onClose(); } };
    const t = setTimeout(() => document.addEventListener("pointerdown", down, true), 0);
    document.addEventListener("keydown", key, true);
    return () => { clearTimeout(t); document.removeEventListener("pointerdown", down, true); document.removeEventListener("keydown", key, true); };
  }, [onClose]);
  const pick = (id: string, el: HTMLElement) => { onClose(); dispatch({ type: "setGroupCurrent", group: group.group, id }); runUiAction(a, id, el); };
  return createPortal(
    <div className={cx("kpalette fixed z-70 bg-bench border border-line shadow-panel flex gap-0", dock === "top" ? "flex-col" : "flex-row")}
      style={{ ...style, padding: PALETTE_BORDER - 1 + "px" }} ref={ref} data-group={group.group}>
      {group.items.map((it) => {
        const ro = viewOnlyWhy(viewOnly, it.id); const why = unavailable(a, it.id) || ro;
        return (
          <button type="button" key={it.id} title={titleFor(a, it.id)} data-uiact={it.id} aria-disabled={why ? true : undefined}
            className={cx(KB, dock === "top" ? "my-px" : "mx-px", why && "desk")}
            onClick={(ev) => { if (!why) pick(it.id, ev.currentTarget); }}
            // BITMAP_BUTTON::AcceptDragInAsClick: a press that began on the toolbar and is released here is a click
            onPointerUp={(ev) => { if (armed.current && !why) { armed.current = false; pick(it.id, ev.currentTarget); } }}>
            <KIcon name={(actionMeta(it.id) || it).icon || "options_generic"} />
          </button>
        );
      })}
    </div>, document.body);
}

function GroupButton({ group, a }: { group: GroupItem; a: Avail }) {
  const wrap = useRef<HTMLDivElement>(null);
  const groupCurrent = useApp((s) => s.groupCurrent);
  const view = useApp((s) => s.view);
  const [open, setOpen] = useState(false);
  const hold = useRef<number>(0);
  const press = useRef<[number, number] | null>(null);
  const armed = useRef(false);       // the press that opened the palette is still down
  const swallow = useRef(false);     // its release must not click the toolbar button
  useEffect(() => { if (view !== "editor") setOpen(false); }, [view]);
  useEffect(() => {
    const up = () => { press.current = null; clearTimeout(hold.current); setTimeout(() => { armed.current = false; }, 0); };
    window.addEventListener("pointerup", up); return () => window.removeEventListener("pointerup", up);
  }, []);
  const cur = groupCurrent[group.group] || group.items[0].id;
  const item = group.items.find((i) => i.id === cur) || group.items[0];
  const popup = () => { clearTimeout(hold.current); if (press.current) { armed.current = true; swallow.current = true; } setOpen(true); };
  const close = useCallback(() => setOpen(false), []);
  return (
    <div className="kgroup relative flex-none" data-group={group.group} ref={wrap}
      onPointerDown={(ev) => {
        if (ev.button !== 0) return;
        if ((ev.target as Element).closest(".karrow")) return;
        press.current = [ev.clientX, ev.clientY]; swallow.current = false;
        hold.current = window.setTimeout(popup, PALETTE_OPEN_DELAY);
      }}
      // wxEVT_AUITOOLBAR_BEGIN_DRAG: dragging off a group's button opens its palette at once
      onPointerMove={(ev) => { const p = press.current; if (p && (ev.buttons & 1) && !open && Math.hypot(ev.clientX - p[0], ev.clientY - p[1]) > 4) popup(); }}
      onClickCapture={(ev) => { if (swallow.current) { swallow.current = false; ev.stopPropagation(); ev.preventDefault(); } }}>
      <ActionButton item={item} a={a} main />
      {/* ACTION_TOOLBAR::OnCustomRender: the corner triangle, 1/5 of the button high, marks a group */}
      <button type="button" className="karrow absolute right-px bottom-px w-1.5 h-1.5 p-0 border-0 bg-transparent text-ink [.kgroup:has(>.desk)>&]:text-ink-3" title={group.group}
        tabIndex={-1} aria-label={group.group} onClick={(ev) => { ev.stopPropagation(); setOpen((o) => !o); }}>
        <svg className="block w-full h-full" viewBox="0 0 6 6"><path d="M6 0V6H0z" fill="currentColor" /></svg>
      </button>
      {open && wrap.current ? <Palette group={group} wrap={wrap.current} a={a} onClose={close} armed={armed} /> : null}
    </div>
  );
}

// ---------------------------------------------------------------- the aux bar's controls
/** EDA_DRAW_FRAME::UpdateGridSelectBox: GRID_MENU::BuildChoiceList in the user units, "---", "Edit Grids...". */
function GridSelect() {
  const gridPitch = useApp((s) => s.viewport.gridPitch);
  const grids = useApp((s) => s.viewport.gridChoices);
  const units = useApp((s) => s.viewport.units);
  const lastImperial = useApp((s) => s.viewport.lastImperial);
  const sch = useApp((s) => s.document.editor === "sch");
  const at = grids.findIndex((g) => Math.abs(g.mm - gridPitch) < 1e-9);
  const options: SelectOption[] = grids.map((g, i) => ({ value: String(i), label: gridChoiceText(g, units, lastImperial, sch ? "sch" : "pcb") }));
  options.push({ value: "sep", label: "---", sep: true }, { value: "edit", label: "Edit Grids..." });
  // EDA_DRAW_FRAME::OnSelectGrid: the last entry runs ACTIONS::gridProperties, the others ACTIONS::gridPreset
  return <Select id="gridSel" className={KSEL} title="Grid" options={options} value={at < 0 ? "" : String(at)} blurOnPick
    onChange={(v) => { if (v === "edit") dispatch({ type: "action", id: "gridProperties" }); else if (v !== "sep" && grids[Number(v)]) dispatch({ type: "setGrid", pitch: grids[Number(v)].mm }); }} />;
}
/** EDA_DRAW_FRAME::UpdateZoomSelectBox / SyncZoomSelectBox: "Zoom Auto", then "Zoom %.2f" for each of the window's zoom
 *  factors; an off-preset zoom shows as its own entry just below Zoom Auto. */
function ZoomSelect() {
  const kzoom = useApp((s) => s.viewport.kzoom);
  const editor = useApp((s) => s.document.editor);
  const list = ZOOM_LIST[editor === "sch" ? "sch" : "pcb"];
  const preset = list.findIndex((f) => Math.abs(f - kzoom) <= f * 1e-3);
  const options: SelectOption[] = [{ value: "auto", label: "Zoom Auto" }];
  if (preset < 0) options.push({ value: "custom", label: `Zoom ${kzoom.toFixed(2)}` });
  for (const f of list) options.push({ value: String(f), label: `Zoom ${f.toFixed(2)}` });
  return <Select id="zoomSel" className={KSEL} title="Zoom" options={options} value={preset < 0 ? "custom" : String(list[preset])} blurOnPick
    onChange={(v) => { if (v === "auto") dispatch({ type: "setZoom", zoom: "auto" }); else if (v !== "custom") dispatch({ type: "setZoom", zoom: Number(v) }); }} />;
}
/** PCB_ACTION_TOOLBAR_CONTROLS::currentVariant: GetVariantNamesForUI, and in the schematic editor a "---" separator
 *  and "Add New Design Variant..." (UpdateVariantSelectionCtrl); choosing calls onVariantSelected. */
function VariantSelect() {
  const v = useApp((s) => s.variant);
  const names = v && v.names.length ? v.names : ["< Default >"];
  const value = v && v.current ? v.current : names[0];
  const options: SelectOption[] = names.map((n) => ({ value: n, label: n }));
  if (v && v.sch) options.push({ value: "---", label: "---", sep: true }, { value: "Add New Design Variant...", label: "Add New Design Variant..." });
  return <Select className={KSEL} title="Select the current variant to display and edit." data={{ k: "current-variant" }} options={options} value={value} blurOnPick
    onChange={(name) => dispatch({ type: "setVariant", name })} />;
}

function Control({ item }: { item: ControlItem }) {
  const c = item.control;
  if (c === "ipcScripting") return null;
  let inner: ReactElement | null = null;
  if (c === "currentVariant") inner = <VariantSelect />;
  else if (c === "overrideLocks") inner = <label className="kcheck inline-flex items-center gap-1 text-sm whitespace-nowrap" title="Allow editing locked items"><input type="checkbox" onChange={(ev) => { const ed = (window as unknown as { CollabEditor?: { overrideLocks?: boolean } }).CollabEditor; if (ed) ed.overrideLocks = ev.currentTarget.checked; }} /> Override locks</label>;
  else if (c === "trackWidth") inner = <TrackWidthSelect />;
  else if (c === "viaDiameter") inner = <ViaSizeSelect />;
  else if (c === "viaStack") inner = <ViaStackSelect />;
  else if (c === "layerSelector") inner = <LayerSelect />;
  else if (c === "gridSelect") inner = <GridSelect />;
  else if (c === "zoomSelect") inner = <ZoomSelect />;
  return <span className="kctl inline-flex items-center gap-1 mx-[3px] flex-none" data-control={c}>{inner}</span>;
}

// ---------------------------------------------------------------- bars
/** A 1px rule: 22px tall in the horizontal bars, 22px wide in the vertical ones. */
function Sep({ v }: { v?: boolean }) {
  return <span className={cx("ksep flex-none bg-line", v ? "w-5.5 h-px my-[3px]" : "w-px h-5.5 mx-[3px]")} />;
}
function Items({ items, a, v }: { items: ToolbarItem[]; a: Avail; v?: boolean }) {
  return (
    <>
      {items.map((it, i) => {
        if (isSep(it)) return <Sep v={v} key={"s" + i} />;
        if (isGroup(it)) return <GroupButton group={it} a={a} key={"g" + it.group + i} />;
        if (isControl(it)) return <Control item={it} key={"c" + it.control + i} />;
        return <ActionButton item={it} a={a} key={it.id + i} />;
      })}
    </>
  );
}
function useBar(loc: ToolbarLoc): ToolbarItem[] {
  const editor = useEditor(); const fp = useApp((s) => s.document.docType === "footprint");
  const key = fp ? "fpedit" : editor;   // the Footprint Editor: toolbars_footprint_editor.cpp on the board editor's machinery
  return (key && SPEC.toolbars[key] && SPEC.toolbars[key][loc]) || [];
}

export function TopToolbar() {
  const a = useAvail(); const items = useBar("top");
  const groupCurrent = useApp((s) => s.groupCurrent);
  const plugins = usePluginBarEntries();   // actions of enabled plugins that ask for a button, as KiCad shows them
  // KiCad's own tools keep wxAuiToolBar's chevron; the plugin buttons after them get a strip of their own that
  // scrolls sideways when there are more than fit, so every plugin button stays one click away.
  const buttons = plugins.filter((e) => e.menu);
  return <OverflowBar id="tbTop" cls="min-h-8.5" a={a} entries={barEntries(items, a, groupCurrent)} strip={buttons.length ? <PluginStrip>{buttons.map((e) => <Fragment key={e.key}>{e.node}</Fragment>)}</PluginStrip> : null} />;
}
export function AuxToolbar() {
  const a = useAvail(); const items = useBar("aux");
  const groupCurrent = useApp((s) => s.groupCurrent);
  return <OverflowBar id="tbAux" cls="min-h-7.5 [&[hidden]]:hidden" a={a} entries={barEntries(items, a, groupCurrent)} hidden={!items.length} />;
}
// ---------------------------------------------------------------- overflow (wxAuiToolBar's chevron)
/** One entry of a bar: what to draw in the bar, and what the overflow menu should list for it. */
interface BarEntry { key: string; node: ReactNode; menu?: { id: string; label: string; icon?: string | null; glyph?: string; control?: boolean } | null }

/** The aux bar's controls, titled as wxAuiToolBar's overflow menu titles them (the tool's label). */
const CONTROL_LABELS: Record<string, string> = { currentVariant: "Current variant", overrideLocks: "Override locks", trackWidth: "Track width",
  viaDiameter: "Via size", viaStack: "Via stack", layerSelector: "Active layer", gridSelect: "Grid", zoomSelect: "Zoom" };

/** The overflow menu: the tools that did not fit, in bar order, as a wxAUI drop-down. */
function OverflowMenu({ entries, anchor, onRight, vertical, a, onClose }: { entries: BarEntry[]; anchor: HTMLElement; onRight: boolean; vertical: boolean; a: Avail; onClose: () => void }) {
  const ref = useRef<HTMLDivElement>(null);
  const viewOnly = useApp((s) => s.viewOnly);
  const [style, setStyle] = useState<CSSProperties>({ visibility: "hidden" });
  useLayoutEffect(() => {
    const r = anchor.getBoundingClientRect();
    const { w, h } = ref.current ? menuSize(ref.current) : { w: 220, h: 200 }, vp = menuViewport();
    // a side bar's menu opens beside the bar; a top bar's drops straight down from the chevron, right-aligned to it
    const left = vertical ? (onRight ? r.left - w - 4 : r.right + 4) : r.right - w;
    const top = Math.max(4, Math.min(vertical ? r.bottom - h : r.bottom + 2, vp.h - h - 4));
    setStyle({ left: Math.max(4, Math.min(left, vp.w - w - 4)) + "px", top: top + "px", maxHeight: vp.h - 4 - top + "px", overflowY: "auto" });
    if (ref.current) menuScroller(ref.current);
  }, [anchor, onRight, vertical, entries.length]);
  useEffect(() => {
    const down = (ev: PointerEvent) => { if (ref.current && !ref.current.contains(ev.target as Node) && !anchor.contains(ev.target as Node)) onClose(); };
    const t = setTimeout(() => document.addEventListener("pointerdown", down, true), 0);
    return () => { clearTimeout(t); document.removeEventListener("pointerdown", down, true); };
  }, [anchor, onClose]);
  return createPortal(
    <div className="kpalette koverflow fixed z-70 bg-panel border border-line rounded-md shadow-panel p-1 min-w-50 max-h-[80vh] overflow-y-auto" ref={ref} style={style}>
      {entries.map((e) => {
        const m = e.menu!;
        // wxAuiToolBar cannot re-parent a control into its overflow menu, so it lists it as a
        // disabled item (wx/aui/auibar.cpp OnOverflowClick) — the label alone, exactly as here.
        if (m.control) return <div key={e.key} className="krow flex items-center gap-2 w-full rounded-xs px-2 py-1 text-ink-3 text-left opacity-60">{m.label}</div>;
        const ro = viewOnlyWhy(viewOnly, m.id); const why = unavailable(a, m.id) || ro; const k = keyFor(a, m.id);
        return (
          <button type="button" key={e.key} title={titleFor(a, m.id)} data-uiact={m.id}
            className={cx("krow group flex items-center gap-2 w-full bg-transparent border-0 rounded-xs px-2 py-1 text-ink text-left hover:bg-accent hover:text-on-accent desk:opacity-[.45]", why && "desk")}
            onClick={(ev) => { onClose(); if (!ro) runUiAction(a, m.id, ev.currentTarget); }}>
            {m.glyph ? <Glyph svg={m.glyph} /> : <KIcon name={m.icon || "options_generic"} />}
            <span className="flex-1">{m.label}</span>
            {k ? <kbd className="text-xs font-mono font-normal leading-[normal] text-ink-3 group-hover:text-on-accent">{menuKey(k)}</kbd> : null}
          </button>
        );
      })}
    </div>, document.body);
}

/**
 * A toolbar that behaves like wxAuiToolBar when it does not fit: the tools that would be clipped
 * stay laid out (so the measurement never oscillates) but are made invisible, and an overflow
 * chevron at the end of the bar pops them up as a menu.  Before this the vertical bars ran off the
 * bottom of the window (on 1280x780, 15 of the board's 34 draw tools — delete, measure, comment and
 * pan among them — were unreachable) and the horizontal bars wrapped into a second row, which
 * wxAuiToolBar never does and which stole 19-30 px of canvas at common laptop widths.
 */
/** The plugin buttons at the end of the top bar.  It is as wide as its buttons up to 45% of the bar; past that it
 *  scrolls sideways (wheel, touch, or the arrows that appear at its ends), which KiCad's own toolbar cannot do. */
function PluginStrip({ children }: { children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const [edge, setEdge] = useState({ left: false, right: false });
  const update = useCallback(() => {
    const el = ref.current; if (!el) return;
    const left = el.scrollLeft > 1, right = el.scrollLeft + el.clientWidth < el.scrollWidth - 1;
    setEdge((e) => (e.left === left && e.right === right ? e : { left, right }));
  }, []);
  useLayoutEffect(() => { update(); });
  useEffect(() => {
    const el = ref.current; if (!el) return;
    const ro = typeof ResizeObserver === "function" ? new ResizeObserver(update) : null; if (ro) ro.observe(el);
    // a mouse wheel turns the strip sideways; the page behind it does not move
    const wheel = (e: WheelEvent) => { if (el.scrollWidth <= el.clientWidth) return; const d = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY; if (!d) return; e.preventDefault(); el.scrollLeft += d; };
    el.addEventListener("wheel", wheel, { passive: false });
    return () => { if (ro) ro.disconnect(); el.removeEventListener("wheel", wheel); };
  }, [update]);
  const step = (dir: number) => { const el = ref.current; if (el) el.scrollBy({ left: dir * Math.max(90, el.clientWidth * 0.7), behavior: "smooth" }); };
  const arrow = (dir: number) => (
    <button type="button" className="plg-tb-arrow" data-strip-arrow={dir < 0 ? "left" : "right"} title={dir < 0 ? "Earlier plugin buttons" : "More plugin buttons"} aria-label={dir < 0 ? "Scroll plugin buttons left" : "Scroll plugin buttons right"} onClick={() => step(dir)}>
      <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={dir < 0 ? "M10 3L5 8l5 5" : "M6 3l5 5-5 5"} /></svg>
    </button>
  );
  return (
    <div className="plg-tb-strip" id="tbPlugins" data-strip="">
      <span className="plg-tb-sep" />
      {edge.left ? arrow(-1) : null}
      <div className="plg-tb-scroll" ref={ref} onScroll={update} role="toolbar" aria-label="Plugins">{children}</div>
      {edge.right ? arrow(1) : null}
    </div>
  );
}

function OverflowBar({ id, cls, entries, a, tail, vertical, hidden, strip }: { id: string; cls: string; entries: BarEntry[]; a: Avail; tail?: ReactNode; vertical?: boolean; hidden?: boolean; strip?: ReactNode }) {
  const box = useRef<HTMLDivElement>(null);
  const ref = useRef<HTMLDivElement>(null);
  const more = useRef<HTMLButtonElement>(null);
  const [cut, setCut] = useState(-1);
  const [open, setOpen] = useState(false);
  const cutRef = useRef(-1);
  const chevron = useRef(30);
   // KMORE is a 30 px button; re-measured from the DOM the first time it is shown
  const view = useApp((s) => s.view);
  /**
   * Which tools fit.  Measured against the OUTER box, whose size along the bar does not depend on the
   * answer — the track is `flex-1`, so asking it would make showing the chevron shrink the space that
   * decides whether to show it, and a bar that fits by a hair would flip-flop for ever.  The items keep
   * their boxes either way (`justify-start`, fixed sizes), so their offsets are a stable input too.
   *
   * The offsets are taken as client-rect deltas from the TRACK's own leading edge.  `offsetTop` /
   * `offsetLeft` would be measured from the nearest positioned ancestor — which for these buttons is
   * the document body — so they carry the bar's distance from the top of the page (102 px, more once
   * the top bars are two rows deep) and comparing them against a height cut the bar far too early.
   */
  const measure = useCallback(() => {
    const el = ref.current, outer = box.current; if (!el || !outer) return;
    // the track's own children are the tools, in `entries` order; `#ltools` is a marker, not a tool
    const kids = Array.from(el.children).filter((k) => k.id !== "ltools") as HTMLElement[];
    let n = -1;
    if (kids.length) {
      const cs = getComputedStyle(el);
      const pad = parseFloat(vertical ? cs.paddingBottom : cs.paddingRight) || 0;
      const moreEl = more.current;
      const moreSize = moreEl && (vertical ? moreEl.offsetHeight : moreEl.offsetWidth);
      if (moreSize) chevron.current = moreSize;
      const trackRect = el.getBoundingClientRect();
      const start = vertical ? trackRect.top : trackRect.left;
      // the plugin strip beside the track takes its own width (it never depends on what is cut here)
      const stripEl = outer.querySelector(":scope > [data-strip]") as HTMLElement | null;
      const full = (vertical ? outer.clientHeight : outer.clientWidth) - (stripEl ? stripEl.offsetWidth : 0);
      const endOf = (k: HTMLElement) => { const r = k.getBoundingClientRect(); return (vertical ? r.bottom : r.right) - start; };
      if (endOf(kids[kids.length - 1]) + pad > full + 0.5) {
        const limit = full - chevron.current - pad;
        n = kids.findIndex((k) => endOf(k) > limit);
        n = n < 0 ? kids.length : Math.max(n, 1);
      }
    }
    // hide the tail without taking it out of the flow, so the next measurement sees the same boxes
    kids.forEach((k, i) => { const off = n >= 0 && i >= n; k.style.visibility = off ? "hidden" : ""; k.style.pointerEvents = off ? "none" : ""; });
    if (n !== cutRef.current) { cutRef.current = n; setCut(n); }
  }, [vertical]);
  useLayoutEffect(() => { measure(); });
  useEffect(() => {
    const outer = box.current; if (!outer) return;
    const ro = typeof ResizeObserver === "function" ? new ResizeObserver(measure) : null;
    if (ro) ro.observe(outer);
    window.addEventListener("resize", measure);
    // web fonts and the icon sheet land after the first layout and change every button's size
    if (typeof document !== "undefined" && (document as any).fonts && (document as any).fonts.ready) (document as any).fonts.ready.then(measure).catch(() => {});
    return () => { if (ro) ro.disconnect(); window.removeEventListener("resize", measure); };
  }, [measure]);
  useEffect(() => { if (cut < 0 || view !== "editor") setOpen(false); }, [cut, view]);
  const hiddenEntries = cut >= 0 ? entries.slice(cut).filter((e) => e.menu) : [];
  return (
    <div id={id} className={cx(vertical ? KTB_V : KTB, cls)} ref={box} hidden={hidden}>
      <div className={vertical ? KTB_V_INNER : KTB_INNER} ref={ref}>
        {entries.map((e) => <Fragment key={e.key}>{e.node}</Fragment>)}
        {tail}
      </div>
      <button type="button" ref={more} data-more="" hidden={cut < 0} title="More tools" aria-label="More tools"
        className={cx(KMORE, vertical ? "mb-1" : "self-center mr-1")} onClick={() => setOpen((o) => !o)}>
        <svg className="w-3.5 h-3.5" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"><path d="M3 4l5 4 5-4M3 9l5 4 5-4" /></svg>
      </button>
      {strip}
      {open && cut >= 0 && more.current && hiddenEntries.length
        ? <OverflowMenu entries={hiddenEntries} anchor={more.current} onRight={id === "tbRight"} vertical={!!vertical} a={a} onClose={() => setOpen(false)} /> : null}
    </div>
  );
}

/** The spec's items as bar entries, each carrying what the overflow menu should show for it. */
function barEntries(items: ToolbarItem[], a: Avail, groupCurrent: Record<string, string>, vertical?: boolean): BarEntry[] {
  return items.map((it, i) => {
    if (isSep(it)) return { key: "s" + i, node: <Sep v={vertical} />, menu: null };
    if (isGroup(it)) {
      const cur = groupCurrent[it.group] || it.items[0].id;
      const item = it.items.find((x) => x.id === cur) || it.items[0];
      const meta = actionMeta(item.id) || item;
      return { key: "g" + it.group + i, node: <GroupButton group={it} a={a} />, menu: { id: item.id, label: meta.label || item.id, icon: meta.icon } };
    }
    if (isControl(it)) return { key: "c" + it.control + i, node: <Control item={it} />,
      menu: it.control === "ipcScripting" ? null : { id: "", label: CONTROL_LABELS[it.control] || it.control, control: true } };
    const meta = actionMeta(it.id) || it;
    return { key: it.id + i, node: <ActionButton item={it} a={a} />, menu: { id: it.id, label: meta.label || it.id, icon: meta.icon } };
  });
}

export function LeftOptionsToolbar() {
  const a = useAvail(); const items = useBar("left");
  const groupCurrent = useApp((s) => s.groupCurrent);
  return <OverflowBar id="tbLeft" cls="border-r border-line" vertical a={a} entries={barEntries(items, a, groupCurrent, true)} />;
}
export function RightDrawToolbar() {
  const a = useAvail(); const items = useBar("right");
  const tool = useApp((s) => s.tool.current);
  const groupCurrent = useApp((s) => s.groupCurrent);
  const moduleTools = useApp((s) => s.tool.moduleTools);
  const isModuleTool = a.moduleTools.has(tool);
  const entries = barEntries(items, a, groupCurrent, true);
  entries.push({ key: "extrasep", node: <Sep v />, menu: null });
  for (const e of EXTRA_TOOLS) {
    const avail = a.appTools.has(e.tool);
    entries.push({
      key: e.id,
      node: (
        <button type="button" className={cx(KB, "glyph", !avail && "desk", tool === e.tool && "on")} data-uiact={e.id} data-ktool={e.tool}
          title={e.name + (avail && e.key ? `  (${keyName(e.key)})` : "")} onClick={(ev) => runUiAction(a, e.id, ev.currentTarget)}>
          <Glyph svg={e.glyph} />
        </button>
      ),
      menu: { id: e.id, label: e.name, glyph: e.glyph },
    });
  }
  return (
    <OverflowBar id="tbRight" cls="border-l border-line" vertical a={a} entries={entries}
      // sch-tools.js reads `#ltools .tb.on` (data-modtool / data-tool) for the active tool and
      // `#ltools [data-modtool="wire"]` to know the schematic module is in charge.
      tail={
        <span id="ltools" hidden>
          <i className="tb on" data-modtool={isModuleTool ? tool : undefined} data-tool={isModuleTool ? undefined : tool} />
          {moduleTools.map((t) => <i key={t.id} className="tb" data-modtool={t.id} />)}
        </span>
      } />
  );
}
